// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(address caller, uint256 amount, address beneficiary) public {
        vm.assume(caller != address(0));
        vm.assume(beneficiary != address(0));
        vm.assume(amount > 0 && amount <= type(uint112).max);
        vm.assume(caller != beneficiary);
        vm.assume(caller != address(this));
        vm.assume(beneficiary != address(this));

        address mAsset = c.depositToken();
        address savings = address(c.savings());

        vm.prank(caller);
        c.approveMax();

        deal(mAsset, caller, amount);

        vm.startPrank(caller);
        IERC20(mAsset).approve(savings, amount);
        c.supplyTokenTo(amount, beneficiary);
        vm.stopPrank();

        uint256 callerBalance = c.imBalances(caller);
        uint256 beneficiaryBalance = c.imBalances(beneficiary);
        assertTrue(beneficiaryBalance > 0 && callerBalance == 0);
    }
}

