        vm.assume(caller != address(0) && recipient != address(0) && caller != recipient);
        vm.assume(amount > 0 && amount <= type(uint128).max);

        // Record balances before
        uint256 callerBalBefore = c.imBalances(caller);
        uint256 recipientBalBefore = c.imBalances(recipient);

        // Execute supplyTokenTo as caller
        vm.prank(caller);
        c.supplyTokenTo(amount, recipient);

        uint256 callerBalAfter = c.imBalances(caller);
