interface IERC20 {
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(uint256 depositAmount) public {
        // 1. bound to admissible domain: amount > 0 and not exceeding max
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2);
        // 2. Setup: first decrease the allowance by performing a depositSavings via the savings contract directly
        //    This simulates a prior operation that reduced the allowance from max.
        address savingsAddr = address(c.savings());
        // Actor with sufficient mAsset balance
        address actor = makeAddr("actor");
        address mAssetAddr = address(c.mAsset());
        deal(mAssetAddr, actor, type(uint256).max);
        vm.startPrank(actor);
        // Approve C to spend mAsset
        IERC20(mAssetAddr).approve(address(c), type(uint256).max);
        // Supply tokens to C which internally calls depositSavings on the savings contract, consuming allowance
        c.supplyTokenTo(depositAmount, actor);
        vm.stopPrank();

        // The allowance for savings contract is now less than max.
        // Call approveMax on the reference (or mutant) contract.
        vm.prank(actor);
        c.approveMax();

        // After approveMax, try another depositSavings call via the savings contract directly.
        // This should succeed if allowance is reset to max, revert otherwise.
        // DepositInterest on savings is a convenient function that requires allowance.
        // We call savings.depositInterest which consumes allowance, testing the allowance state.
        vm.prank(actor);
        (bool success, ) = savingsAddr.call(abi.encodeWithSignature("depositInterest(uint256)", depositAmount));
        // The general rule: after approveMax, a depositInterest call should not revert.
        // The reference resets allowance to max -> success; mutant does not -> revert.
        assertTrue(success);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(uint256 initialDeposit, uint256 spendAmount) public {
        // Bound to reasonable ranges to keep fuzzing effective
        initialDeposit = bound(initialDeposit, 1, type(uint128).max);
        spendAmount = bound(spendAmount, 1, initialDeposit);

        // Deploy an adversarial helper that acts as the savings contract
        // It will reduce the allowance after a deposit, simulating fee/migration logic
        AllowanceReducer reducer = new AllowanceReducer();

        // Setup: Give C some mAsset (via a mock call that doesn't exist, but we can't deploy the real mAsset)
        // Instead, we'll simulate the state through C's own accounting.
        // We need c to hold mAsset balance and have a non-max allowance.
        // Since we can't directly manipulate mAsset or savings, we use the fact that
        // C's constructor approves max. We'll interact through a helper that calls
        // approveMax and then reduces allowance afterwards.

        // Give the reducer some ether for gas
        vm.deal(address(reducer), 1 ether);

        // First, call approveMax to ensure initial state is max
        vm.prank(address(this));
        c.approveMax();

        // Now have the reducer call approveMax, then simulate a fee that reduces allowance
        reducer.reduceAllowanceAfterApproveMax(c, spendAmount);

        // The property: after approveMax was called (even if someone else called it),
        // the allowance should be max. But the mutant didn't reset it.
        // We check the allowance via public getter of mAsset (which is immutable public)
        // Actually, we observe through C's public surface: the allowance of mAsset for savings
        IERC20 mAsset = IERC20(c.mAsset());
        address savings = address(c.savings());
        uint256 allowance = mAsset.allowance(address(c), savings);

        // After approveMax was called (by the reducer's external call), allowance should be max
        // The reducer called approveMax, then immediately reduced allowance.
        // If approveMax resets to max, allowance is spendAmount (reduced from max).
        // The mutant didn't reset, so allowance remains 0 after reduce from 0.
        // But wait - we need a case where the mutant breaks.
        // Let's check: allowance should be exactly spendAmount (the reducer reduced from max to spendAmount)
        // In mutant, approveMax did nothing, so reduce reverts (safeDecreaseAllowance underflow) or sets to 0.
        // Actually, safeDecreaseAllowance checks oldAllowance >= value, so if allowance is 0, it reverts.
        // So the property is: the call to approveMax by the reducer succeeds (doesn't revert)
        // and after it, the allowance is at least the reducer's attempted reduction.
        // We can check the reducer's success flag.
        assertTrue(reducer.success());
    }
}

// Adversarial helper: calls approveMax, then immediately reduces allowance to simulate a fee
// This mimics an external party (the savings contract or a governance action) that
// reduces the allowance after approveMax. The reference resets to max, so reduction works.
// The mutant does nothing, so reduction reverts due to insufficient old allowance.
contract AllowanceReducer {
    bool public success;

    function reduceAllowanceAfterApproveMax(C c, uint256 amount) external {
        // Call approveMax - the buggy version does nothing
        try c.approveMax() {
            // Now try to reduce the allowance from max to amount
            // We use forceApprove or safeDecreaseAllowance through c's own methods?
            // Actually, we can directly interact with mAsset since we know the addresses
            // But we must go through C's public surface? The assertion is on C's behavior.
            // The key is: after approveMax, the allowance should be max, so a reduction to 'amount' works.
            // We'll make a raw call to mAsset to reduce allowance, simulating a governance action.
            IERC20 mAsset = IERC20(c.mAsset());
            address savings = address(c.savings());

            // Use forceApprove to set a lower allowance (simulating a fee that leaves 'amount')
            // forceApprove sets to 0 then to amount
            bytes memory callData = abi.encodeWithSelector(mAsset.approve.selector, savings, amount);
            (bool ok1,) = address(mAsset).call(callData);
            if (ok1) {
                success = true;
            } else {
                // If first approve failed, try zero then amount
                bytes memory zeroData = abi.encodeWithSelector(mAsset.approve.selector, savings, 0);
                (bool okZero,) = address(mAsset).call(zeroData);
                if (okZero) {
                    (bool ok2,) = address(mAsset).call(callData);
                    success = ok2;
                }
            }
        } catch {
            success = false;
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(ISavingsContractV2(address(new MockSavings())));
    }
    function testFuzz_property(uint256 mAssetAmount, uint256 initialCallAmount) public {
        vm.assume(mAssetAmount > 0);
        vm.assume(initialCallAmount > 0);
        MockSavings savings = MockSavings(address(c.savings()));
        address mAssetAddr = address(c.mAsset());
        // Deploy a mock mAsset token that records transfers and handles approve
        MockERC20 token = new MockERC20();
        // Override the immutable savings contract's underlying() to return the mock token
        savings.setUnderlying(address(token));
        // Re-create C with the mock savings so that the immutable mAsset is the mock token
        c = new C(ISavingsContractV2(address(savings)));
        // Mint tokens to the caller and approve C to spend
        address caller = address(this);
        token.mint(caller, mAssetAmount + initialCallAmount);
        vm.prank(caller);
        token.approve(address(c), mAssetAmount + initialCallAmount);
        // First, call supplyTokenTo to decrease the allowance below max
        vm.startPrank(caller);
        token.approve(address(c), type(uint256).max);
        c.supplyTokenTo(initialCallAmount, caller);
        vm.stopPrank();
        // Now call approveMax
        vm.prank(address(this));
        c.approveMax();
        // Now attempt a second supplyTokenTo; the reference should not revert, the mutant may revert due to insufficient allowance
        vm.startPrank(caller);
        token.approve(address(c), type(uint256).max); // ensure initial max before the first call is cleared
        c.supplyTokenTo(initialCallAmount, caller);
        vm.stopPrank();
        bool ok;
        vm.startPrank(caller);
        token.approve(address(c), type(uint256).max); // needed for the test call to succeed if allowance was reset
        try c.supplyTokenTo(mAssetAmount, caller) { ok = true; } catch { ok = false; }
        vm.stopPrank();
        assertTrue(ok);
    }
}

