pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }

    function testFuzz_property(address caller, uint256 amount) public {
        // Keep amount in a wide positive range to avoid zero deposits
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= type(uint128).max);

        // The reference allows only the contract owner to call approveMax;
        // the mutant allows anyone. We observe the effect on the allowance
        // that `approveMax` sets to type(uint256).max.
        // We need an external party that actually holds tokens to deposit,
        // but `mAsset` is a faked IERC20 set up by the constructor.
        // The constructor already approves the savings contract for max.
        // Calling approveMax again from a non-owner will reset the allowance
        // to max in the mutant, but revert in the reference.
        // We wrap the call and check success.
        bool ok;
        vm.prank(caller);
        try c.approveMax() {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference, the call reverts for any caller != contractOwner;
        // in the mutant, it succeeds for every caller.
        // Thus, the truth of `ok` directly reveals the difference.
        // The general rule: approveMax must revert for every caller except the owner.
        // The reference holds this (always reverts for non-owner),
        // the mutant violates it (succeeds for any caller).
        assertTrue(!ok);
    }
}

