import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new MockSavings())); }
    function testFuzz_property(uint256 amount, address addr) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 1e18);
        vm.assume(addr != address(0) && addr != address(c) && addr != address(this));
        // supply token to set imBalances for addr
        vm.startPrank(address(this));
        // deal underlying token to this contract and approve
        MockERC20(address(c.mAsset())).mint(address(this), amount);
        MockERC20(address(c.mAsset())).approve(address(c), amount);
        c.supplyTokenTo(amount, addr);
        vm.stopPrank();
        // now check balanceOfToken equals imBalances * exchangeRate / 1e18
        uint256 exchangeRate = c.savings().exchangeRate();
        uint256 imBal = c.imBalances(addr);
        uint256 expected = (imBal * exchangeRate) / 1e18;
        uint256 actual = c.balanceOfToken(addr);
        assertTrue(actual == expected);
    }
}
contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function mint(address to, uint256 amount) external { balanceOf[to] += amount; }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount, "insufficient balance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
}
contract MockSavings {
    uint256 public exchangeRate = 1.2e18;
    function underlying() external view returns (address) { return address(0x1); }
    function depositSavings(uint256 amount) external returns (uint256 creditsIssued) {
        creditsIssued = (amount * 1e18) / exchangeRate;
    }
    function redeemUnderlying(uint256) external returns (uint256) { return 0; }
}

