pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(uint256 amount) public {
        // Keep amount in a wide admissible range
        vm.assume(amount > 0 && amount <= type(uint128).max);

        // Deploy a helper that can supply tokens to the pool and create a non‑zero
        // caller balance, so the bug is observable.
        Helper helper = new Helper(address(c));

        // Give some mAsset to the helper so it can supplyTokenTo the test contract.
        address mAsset = c.depositToken();
        deal(mAsset, address(helper), amount);
        vm.prank(address(helper));
        helper.supply(amount);

        // Record contract's mAsset balance before redemption
        uint256 contractBalanceBefore = IERC20(mAsset).balanceOf(address(c));

        // Redeem from the test contract itself
        vm.prank(address(this));
        uint256 returned = c.redeemToken(amount);

        // Record contract's mAsset balance after redemption
        uint256 contractBalanceAfter = IERC20(mAsset).balanceOf(address(c));

        // The returned amount must equal the net mAsset increase observed on the contract
        assertTrue(returned == contractBalanceAfter - contractBalanceBefore);
    }
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

contract Helper {
    C public immutable pool;
    constructor(address _pool) { pool = C(_pool); }

    function supply(uint256 amount) external {
        IERC20 token = IERC20(pool.depositToken());
        token.approve(address(pool), amount);
        pool.supplyTokenTo(amount, address(this));
    }
}

