pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(ISavingsContractV2(address(0))); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        // Deploy adversarial mAsset that returns different balance for contract vs caller
        AdversarialToken token = new AdversarialToken();
        // Deploy adversarial savings that implements redeemUnderlying without reverting
        AdversarialSavings savings = new AdversarialSavings(address(token), amount);
        // Deploy real contract with the adversarial savings
        c = new C(ISavingsContractV2(address(savings)));
        token.mint(actor, amount);
        vm.deal(actor, 0);
        vm.startPrank(actor);
        token.approve(address(c), amount);
        c.supplyTokenTo(amount, actor);
        vm.stopPrank();
        uint256 creditsBefore = c.imBalances(actor);
        vm.prank(actor);
        try c.redeemToken(amount) returns (uint256) {
            uint256 creditsAfter = c.imBalances(actor);
            uint256 creditsBurned = creditsBefore - creditsAfter;
            assertTrue(creditsBurned == savings.redeemedCredits());
        } catch {
            // Revert is acceptable, property only holds when call completes
        }
    }
}

contract AdversarialToken {
    mapping(address => uint256) public balances;
    mapping(address => mapping(address => uint256)) public allowances;
    function mint(address to, uint256 amount) external { balances[to] += amount; }
    function balanceOf(address addr) external view returns (uint256) { return balances[addr]; }
    function approve(address spender, uint256 amount) external returns (bool) {
        allowances[msg.sender][spender] = amount;
        return true;
    }
    function allowance(address owner, address spender) external view returns (uint256) {
        return allowances[owner][spender];
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowances[from][msg.sender] >= amount, "insufficient allowance");
        require(balances[from] >= amount, "insufficient balance");
        allowances[from][msg.sender] -= amount;
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }
    function transfer(address to, uint256 amount) external returns (bool) {
        require(balances[msg.sender] >= amount, "insufficient balance");
        balances[msg.sender] -= amount;
        balances[to] += amount;
        return true;
    }
}

contract AdversarialSavings is ISavingsContractV2 {
    address public underlying;
    uint256 public depositedAmount;
    uint256 public redeemedCredits;
    constructor(address _underlying, uint256 _amount) {
        underlying = _underlying;
        depositedAmount = _amount;
    }
    function depositSavings(uint256 _amount) external returns (uint256 creditsIssued) {
        return _amount;
    }
    function depositSavings(uint256 _amount, address) external returns (uint256 creditsIssued) {
        return _amount;
    }
    function redeemUnderlying(uint256 _amount) external returns (uint256 creditsBurned) {
        redeemedCredits = _amount;
        return _amount;
    }
    function exchangeRate() external view returns (uint256) { return 1e18; }
    function redeem(uint256) external returns (uint256) { return 0; }
    function creditBalances(address) external view returns (uint256) { return 0; }
    function depositInterest(uint256) external {}
    function redeemCredits(uint256) external returns (uint256) { return 0; }
    function balanceOfUnderlying(address) external view returns (uint256) { return 0; }
    function underlyingToCredits(uint256 _underlying) external view returns (uint256) { return _underlying; }
    function creditsToUnderlying(uint256 _credits) external view returns (uint256) { return _credits; }
    function underlying() external view returns (IERC20) { return IERC20(underlying); }
}
